/// Parses a human readable size specification such as "10K" or "4MB".
/// Returns None (and prints a warning for unknown units) on failure.
pub fn convert_min_size(input: &str) -> Option<u64> {
    let mut chars = input.chars().skip_while(|c| !c.is_ascii_digit()).peekable();
    let mut number = String::new();
    while let Some(c) = chars.peek() {
        if c.is_ascii_digit() {
            number.push(*c);
            chars.next();
        } else {
            break;
        }
    }
    let unit: String = chars
        .take_while(|c| c.is_alphanumeric() || *c == '_')
        .collect();
    let base: u64 = number.parse().ok()?;
    let multiplier: u64 = match unit.chars().next().map(|c| c.to_ascii_lowercase()) {
        None | Some('b') => 1,
        Some('k') => 1024,
        Some('m') => 1024 * 1024,
        Some('g') => 1024 * 1024 * 1024,
        Some('t') => 1024u64.pow(4),
        Some('p') => 1024u64.pow(5),
        _ => {
            eprintln!("Ignoring invalid min-size: {}", input);
            return None;
        }
    };
    Some(base.wrapping_mul(multiplier))
}

pub fn get_current_date_epoch_seconds() -> i64 {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    // round down to the start of the (UTC) day
    (now / DAY_SECONDS) * DAY_SECONDS
}

#[derive(Debug, Clone, Copy)]
pub enum TimeOp {
    /// +n : older than n days (time <= curr - (n+1) days)
    Older,
    /// -n : newer than n days (time >= curr - n days)
    Newer,
    /// n : exactly n days ago
    Exact,
}

#[derive(Debug, Clone, Copy)]
pub struct TimeFilter {
    pub op: TimeOp,
    pub days: i64,
    pub current: i64,
}

impl TimeFilter {
    pub fn matches(&self, t: i64) -> bool {
        let d = DAY_SECONDS;
        match self.op {
            TimeOp::Older => t <= self.current - (self.days + 1) * d,
            TimeOp::Newer => t >= self.current - self.days * d,
            TimeOp::Exact => {
                t >= self.current - (self.days + 1) * d && t < self.current - self.days * d
            }
        }
    }
}

pub fn get_filter_time_operator(option_value: Option<&String>, current: i64) -> Option<TimeFilter> {
    let val = option_value?;
    let (op, digits) = if let Some(rest) = val.strip_prefix('+') {
        (TimeOp::Older, rest)
    } else if let Some(rest) = val.strip_prefix('-') {
        (TimeOp::Newer, rest)
    } else {
        (TimeOp::Exact, val.as_str())
    };
    let days = parse_days(digits);
    Some(TimeFilter { op, days, current })
}

fn parse_days(digits: &str) -> i64 {
    // The number of days must be a plain integer.
    let parsed: i64 = digits.parse().expect("invalid data format");
    parsed
}

pub fn get_config(config_from_cli: Option<&String>) -> Config {
    if let Some(path) = config_from_cli {
        let p = Path::new(path);
        if !p.exists() {
            eprintln!("Config file {:?} doesn't exists", path);
            return Config::default();
        }
        return match read_config_file(p) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("Ignoring invalid config file '{}': {}", path, e);
                Config::default()
            }
        };
    }
    if let Some(home) = std::env::var_os("HOME") {
        let home = PathBuf::from(home);
        let candidates = [
            home.join(".dust.toml"),
            home.join(".config").join("dust").join("config.toml"),
        ];
        for c in candidates.iter() {
            if c.exists() {
                if let Ok(cfg) = read_config_file(c) {
                    return cfg;
                }
            }
        }
    }
    Config::default()
}

fn read_config_file(path: &Path) -> Result<Config, String> {
    let ext = path
        .extension()
        .map(|e| e.to_string_lossy().to_lowercase())
        .unwrap_or_default();
    if ext != "toml" {
        return Err("don't know how to parse file".to_string());
    }
    let content =
        std::fs::read_to_string(path).map_err(|_| "couldn't read file".to_string())?;
    toml::from_str::<Config>(&content).map_err(|_| "couldn't parse TOML file".to_string())
}
