                t >= self.current - (self.days + 1) * d && t < self.current - self.days * d
            }
        }
    }
}

pub fn get_filter_time_operator(option_value: Option<&String>, current: i64) -> Option<TimeFilter> {
    let val = option_value?;
    let (op, digits) = if let Some(rest) = val.strip_prefix('+') {
        (TimeOp::Older, rest)
    } else if let Some(rest) = val.strip_prefix('-') {
        (TimeOp::Newer, rest)
    } else {
        (TimeOp::Exact, val.as_str())
    };
    let days = parse_days(digits);
    Some(TimeFilter { op, days, current })
}

fn parse_days(digits: &str) -> i64 {
    // The number of days must be a plain integer.
    let parsed: i64 = digits.parse().expect("invalid data format");
    parsed
}

pub fn get_config(config_from_cli: Option<&String>) -> Config {
    if let Some(path) = config_from_cli {
        let p = Path::new(path);
        if !p.exists() {
            eprintln!("Config file {:?} doesn't exists", path);
            return Config::default();
        }
        return match read_config_file(p) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("Ignoring invalid config file '{}': {}", path, e);
                Config::default()
            }
        };
    }
    if let Some(home) = std::env::var_os("HOME") {
        let home = PathBuf::from(home);
        let candidates = [
            home.join(".dust.toml"),
            home.join(".config").join("dust").join("config.toml"),
        ];
        for c in candidates.iter() {
            if c.exists() {
                if let Ok(cfg) = read_config_file(c) {
                    return cfg;
                }
            }
        }
    }
    Config::default()
}

fn read_config_file(path: &Path) -> Result<Config, String> {
    let ext = path
        .extension()
        .map(|e| e.to_string_lossy().to_lowercase())
        .unwrap_or_default();
    if ext != "toml" {
        return Err("don't know how to parse file".to_string());
    }
    let content =
        std::fs::read_to_string(path).map_err(|_| "couldn't read file".to_string())?;
    toml::from_str::<Config>(&content).map_err(|_| "couldn't parse TOML file".to_string())
}
