        Some(self.cmp(other))
    }
}

impl Ord for Node {
    fn cmp(&self, other: &Self) -> Ordering {
        match self.size.cmp(&other.size) {
            Ordering::Equal => self.name.cmp(&other.name),
            o => o,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FileTime {
    Accessed,
    Changed,
    Modified,
}

pub struct FileInfo {
    pub size: u64,
    pub inode_device: Option<(u64, u64)>,
    pub mtime: i64,
    pub atime: i64,
    pub ctime: i64,
}

pub fn get_metadata(path: &Path, use_apparent_size: bool, follow_links: bool) -> Option<FileInfo> {
    let md = if follow_links {
        fs::metadata(path)
    } else {
        fs::symlink_metadata(path)
    }
    .ok()?;
    let size = if use_apparent_size {
        md.len()
    } else {
        md.blocks() * 512
    };
    Some(FileInfo {
        size,
        inode_device: Some((md.ino(), md.dev())),
        mtime: md.mtime(),
        atime: md.atime(),
        ctime: md.ctime(),
    })
}

pub fn is_filtered_out_due_to_regex(walk_data: &WalkData, path: &Path) -> bool {
    let p = path.as_os_str().to_string_lossy();
    if !walk_data.filter_regex.is_empty() && !walk_data.filter_regex.iter().any(|r| r.is_match(&p)) {
        return true;
    }
    if !walk_data.invert_filter_regex.is_empty()
        && walk_data.invert_filter_regex.iter().any(|r| r.is_match(&p))
    {
        return true;
    }
    false
}

pub fn is_filtered_out_due_to_file_time(walk_data: &WalkData, info: &FileInfo) -> bool {
    if let Some(f) = &walk_data.filter_modified_time {
        if !f.matches(info.mtime) {
            return true;
        }
    }
    if let Some(f) = &walk_data.filter_accessed_time {
        if !f.matches(info.atime) {
            return true;
        }
    }
    if let Some(f) = &walk_data.filter_changed_time {
        if !f.matches(info.ctime) {
            return true;
        }
    }
    false
}

pub fn build_node(
    path: PathBuf,
    children: Vec<Node>,
    _is_symlink: bool,
    is_file: bool,
    depth: usize,
    walk_data: &WalkData,
) -> Option<Node> {
    let info = get_metadata(&path, walk_data.use_apparent_size, walk_data.follow_links)?;

    let filtered = is_filtered_out_due_to_regex(walk_data, &path)
        || is_filtered_out_due_to_file_time(walk_data, &info);

    let own_size = if filtered {
        0
    } else if walk_data.by_filecount {
        if is_file {
            1
        } else {
            0
        }
    } else if let Some(ft) = walk_data.by_filetime {
        let t = match ft {
            FileTime::Accessed => info.atime,
            FileTime::Changed => info.ctime,
            FileTime::Modified => info.mtime,
        };
        if t < 0 {
            0
        } else {
            t as u64
        }
    } else {
        info.size
    };

    let mut node = Node {
        name: path,
        size: 0,
        own_size,
        children,
        inode_device: info.inode_device,
        depth,
    };
    node.recompute_size(walk_data.by_filetime.is_some());
    Some(node)
}
