use std::collections::HashSet;
use std::fs;
use std::io::ErrorKind;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};

use rayon::prelude::*;
use regex::Regex;

use crate::config::TimeFilter;
use crate::node::{build_node, is_filtered_out_due_to_file_time, is_filtered_out_due_to_regex, FileInfo, FileTime, Node};
use crate::progress::{Operation, PAtomicInfo, ORDERING};

#[derive(Default, Debug)]
pub struct RuntimeErrors {
    pub no_permissions: HashSet<String>,
    pub file_not_found: HashSet<String>,
    pub unknown_error: HashSet<String>,
}

pub struct WalkData<'a> {
    pub ignore_directories: HashSet<PathBuf>,
    pub filter_regex: &'a [Regex],
    pub invert_filter_regex: &'a [Regex],
    pub allowed_filesystems: HashSet<u64>,
    pub filter_modified_time: Option<TimeFilter>,
    pub filter_accessed_time: Option<TimeFilter>,
    pub filter_changed_time: Option<TimeFilter>,
    pub use_apparent_size: bool,
    pub by_filecount: bool,
    pub by_filetime: Option<FileTime>,
    pub ignore_hidden: bool,
    pub follow_links: bool,
    pub progress_data: Arc<PAtomicInfo>,
    pub errors: Arc<Mutex<RuntimeErrors>>,
}

pub fn walk_it(dirs: Vec<PathBuf>, walk_data: &WalkData) -> Vec<Node> {
    let mut inodes: HashSet<(u64, u64)> = HashSet::new();
    let mut top_level_nodes = Vec::new();
    for d in dirs {
        let prog_data = &walk_data.progress_data;
        prog_data.clear_state(&d);
        let node = walk(d, walk_data, 0);
        prog_data.state.store(Operation::Preparing as u8, ORDERING);
        if let Some(node) = node {
            if let Some(cleaned) = clean_inodes(node, &mut inodes, walk_data) {
                top_level_nodes.push(cleaned);
            }
        }
    }
    top_level_nodes
}

fn sort_by_inode(a: &Node, b: &Node) -> std::cmp::Ordering {
    match a.inode_device.cmp(&b.inode_device) {
        std::cmp::Ordering::Equal => a.name.cmp(&b.name),
        o => o,
    }
}

fn clean_inodes(node: Node, inodes: &mut HashSet<(u64, u64)>, walk_data: &WalkData) -> Option<Node> {
    if !walk_data.use_apparent_size {
        if let Some(id) = node.inode_device {
            if !inodes.insert(id) {
                return None;
            }
        }
    }
    let mut children = node.children;
    children.sort_by(sort_by_inode);
    let new_children: Vec<Node> = children
        .into_iter()
        .filter_map(|c| clean_inodes(c, inodes, walk_data))
        .collect();
    let mut n = Node {
        name: node.name,
        size: 0,
        own_size: node.own_size,
        children: new_children,
        inode_device: node.inode_device,
        depth: node.depth,
    };
    n.recompute_size(walk_data.by_filetime.is_some());
    Some(n)
}

fn path_is_ignored(path: &Path, walk_data: &WalkData) -> bool {
    if walk_data.ignore_directories.is_empty() {
        return false;
    }
    if walk_data.ignore_directories.contains(path) {
        return true;
    }
    if let Ok(canon) = fs::canonicalize(path) {
        if walk_data.ignore_directories.contains(&canon) {
            return true;
        }
    }
    false
}

fn ignore_file(entry: &fs::DirEntry, walk_data: &WalkData) -> bool {
    let name = entry.file_name();
    let is_dot_file = name.to_string_lossy().starts_with('.');
    if is_dot_file && walk_data.ignore_hidden {
        return true;
    }
    let path = entry.path();
    if path_is_ignored(&path, walk_data) {
        return true;
    }

    if !walk_data.allowed_filesystems.is_empty() {
        let md = if walk_data.follow_links {
            fs::metadata(&path)
        } else {
            fs::symlink_metadata(&path)
        };
        if let Ok(md) = md {
            if !walk_data.allowed_filesystems.contains(&md.dev()) {
                return true;
            }
        }
    }

    let is_dir = entry.file_type().map(|t| t.is_dir()).unwrap_or(false);
    if !is_dir {
        if is_filtered_out_due_to_regex(walk_data, &path) {
            return true;
        }
        let has_time_filter = walk_data.filter_modified_time.is_some()
            || walk_data.filter_accessed_time.is_some()
            || walk_data.filter_changed_time.is_some();
        if has_time_filter {
            if let Ok(md) = fs::symlink_metadata(&path) {
                let info = FileInfo {
                    size: 0,
                    inode_device: None,
                    mtime: md.mtime(),
                    atime: md.atime(),
                    ctime: md.ctime(),
                };
                if is_filtered_out_due_to_file_time(walk_data, &info) {
                    return true;
                }
            }
        }
    }
    false
}

fn record_dir_error(dir: &Path, err: &std::io::Error, walk_data: &WalkData) {
    let mut errors = walk_data.errors.lock().unwrap();
    let p = dir.to_string_lossy().into_owned();
    match err.kind() {
        ErrorKind::PermissionDenied => {
            errors.no_permissions.insert(p);
        }
        ErrorKind::NotFound => {
            errors.file_not_found.insert(p);
        }
        _ => {
            errors.unknown_error.insert(p);
        }
    }
}

pub fn walk(dir: PathBuf, walk_data: &WalkData, depth: usize) -> Option<Node> {
    let prog_data = &walk_data.progress_data;

    let children: Vec<Node> = if dir.is_dir() {
        match fs::read_dir(&dir) {
            Ok(read_dir) => {
                let entries: Vec<_> = read_dir.collect();
                entries
                    .into_par_iter()
                    .filter_map(|entry| {
                        let entry = match entry {
                            Ok(e) => e,
                            Err(_) => return None,
                        };
                        if ignore_file(&entry, walk_data) {
                            return None;
                        }
                        let ft = entry.file_type().ok()?;
                        if ft.is_dir() || (walk_data.follow_links && ft.is_symlink()) {
                            return walk(entry.path(), walk_data, depth + 1);
                        }
                        let node = build_node(
                            entry.path(),
                            vec![],
                            ft.is_symlink(),
                            ft.is_file(),
                            depth + 1,
                            walk_data,
                        );
                        prog_data.num_files.fetch_add(1, ORDERING);
                        if let Some(ref n) = node {
                            prog_data.total_file_size.fetch_add(n.size, ORDERING);
                        }
                        node
                    })
                    .collect()
            }
            Err(e) => {
                record_dir_error(&dir, &e, walk_data);
                vec![]
            }
        }
    } else {
        if !dir.is_file() {
            let mut errors = walk_data.errors.lock().unwrap();
            errors
                .file_not_found
                .insert(dir.to_string_lossy().into_owned());
        }
        vec![]
    };
    build_node(dir, children, false, false, depth, walk_data)
}
