                };
                if is_filtered_out_due_to_file_time(walk_data, &info) {
                    return true;
                }
            }
        }
    }
    false
}

fn record_dir_error(dir: &Path, err: &std::io::Error, walk_data: &WalkData) {
    let mut errors = walk_data.errors.lock().unwrap();
    let p = dir.to_string_lossy().into_owned();
    match err.kind() {
        ErrorKind::PermissionDenied => {
            errors.no_permissions.insert(p);
        }
        ErrorKind::NotFound => {
            errors.file_not_found.insert(p);
        }
        _ => {
            errors.unknown_error.insert(p);
        }
    }
}

pub fn walk(dir: PathBuf, walk_data: &WalkData, depth: usize) -> Option<Node> {
    let prog_data = &walk_data.progress_data;

    let children: Vec<Node> = if dir.is_dir() {
        match fs::read_dir(&dir) {
            Ok(read_dir) => {
                let entries: Vec<_> = read_dir.collect();
                entries
                    .into_par_iter()
                    .filter_map(|entry| {
                        let entry = match entry {
                            Ok(e) => e,
                            Err(_) => return None,
                        };
                        if ignore_file(&entry, walk_data) {
                            return None;
                        }
                        let ft = entry.file_type().ok()?;
                        if ft.is_dir() || (walk_data.follow_links && ft.is_symlink()) {
                            return walk(entry.path(), walk_data, depth + 1);
                        }
                        let node = build_node(
                            entry.path(),
                            vec![],
                            ft.is_symlink(),
                            ft.is_file(),
                            depth + 1,
                            walk_data,
                        );
                        prog_data.num_files.fetch_add(1, ORDERING);
                        if let Some(ref n) = node {
                            prog_data.total_file_size.fetch_add(n.size, ORDERING);
                        }
                        node
                    })
                    .collect()
            }
            Err(e) => {
                record_dir_error(&dir, &e, walk_data);
                vec![]
            }
        }
    } else {
        if !dir.is_file() {
            let mut errors = walk_data.errors.lock().unwrap();
            errors
                .file_not_found
                .insert(dir.to_string_lossy().into_owned());
        }
        vec![]
    };
    build_node(dir, children, false, false, depth, walk_data)
}
