use std::collections::{BinaryHeap, HashSet};
use std::path::{Path, PathBuf};

use crate::display_node::DisplayNode;
use crate::node::Node;

pub struct AggregateData {
    pub min_size: Option<u64>,
    pub only_dir: bool,
    pub only_file: bool,
    pub number_of_lines: usize,
    pub depth: usize,
    pub using_a_filter: bool,
}

pub fn get_biggest(
    top_level_nodes: Vec<Node>,
    display_data: &AggregateData,
    keep_collapsed: &HashSet<PathBuf>,
) -> Option<DisplayNode> {
    if top_level_nodes.is_empty() {
        return None;
    }
    let number_top_level_nodes = top_level_nodes.len();
    let root = if number_top_level_nodes > 1 {
        let size = top_level_nodes
            .iter()
            .fold(0u64, |acc, n| acc.wrapping_add(n.size));
        Node {
            name: PathBuf::from("(total)"),
            size,
            own_size: 0,
            children: top_level_nodes,
            inode_device: None,
            depth: 0,
        }
    } else {
        top_level_nodes.into_iter().next().unwrap()
    };

    if display_data.only_file {
        let mut leaves: Vec<&Node> = Vec::new();
        collect_leaves(&root, 1, display_data.depth, &mut leaves);
        let mut heap: BinaryHeap<&Node> = BinaryHeap::new();
        for leaf in leaves {
            if passes_filters(leaf, display_data) {
                heap.push(leaf);
            }
        }
        let mut allowed: Vec<&Node> = Vec::new();
        for _ in 0..display_data.number_of_lines {
            match heap.pop() {
                Some(n) => allowed.push(n),
                None => break,
            }
        }
        let mut children: Vec<DisplayNode> = allowed
            .into_iter()
            .map(|n| DisplayNode {
                name: n.name.clone(),
                size: n.size,
                children: vec![],
            })
            .collect();
        children.sort_by(|a, b| b.cmp(a));
        return Some(DisplayNode {
            name: root.name.clone(),
            size: root.size,
            children,
        });
    }

    let mut heap: BinaryHeap<&Node> = BinaryHeap::new();
    // Children of the (total) node are always considered regardless of depth
    let ignore_depth = number_top_level_nodes > 1;
    heap = add_children(display_data, &root, heap, 1, ignore_depth);
    fill_remaining_lines(heap, &root, display_data, keep_collapsed)
}

fn collect_leaves<'a>(node: &'a Node, depth: usize, max_depth: usize, out: &mut Vec<&'a Node>) {
    if depth > max_depth.saturating_add(0) && max_depth != usize::MAX {
        return;
    }
    for c in &node.children {
        if depth > max_depth {
            continue;
        }
        if c.children.is_empty() {
            out.push(c);
        } else {
            collect_leaves(c, depth + 1, max_depth, out);
        }
    }
}

fn passes_filters(c: &Node, display_data: &AggregateData) -> bool {
    if display_data.using_a_filter && !(c.name.is_file() || c.size > 0) {
        return false;
    }
    if let Some(min) = display_data.min_size {
        if c.size <= min {
            return false;
        }
    }
    if display_data.only_dir && !c.name.is_dir() {
        return false;
    }
    true
}

fn add_children<'a>(
    display_data: &AggregateData,
    file_or_folder: &'a Node,
    mut heap: BinaryHeap<&'a Node>,
    child_depth: usize,
    ignore_depth: bool,
) -> BinaryHeap<&'a Node> {
    if ignore_depth || child_depth <= display_data.depth {
        for c in file_or_folder.children.iter() {
            if passes_filters(c, display_data) {
                heap.push(c);
            }
        }
    }
    heap
}

struct Allowed<'a> {
    node: &'a Node,
    depth: usize,
}

fn fill_remaining_lines<'a>(
    mut heap: BinaryHeap<&'a Node>,
    root: &'a Node,
    display_data: &AggregateData,
    keep_collapsed: &HashSet<PathBuf>,
) -> Option<DisplayNode> {
    let mut allowed_nodes: HashSet<*const Node> = HashSet::new();
    allowed_nodes.insert(root as *const Node);

    // depth of each node is derived from the tree position; we track it via a map
    let mut depths: std::collections::HashMap<*const Node, usize> = std::collections::HashMap::new();
    depths.insert(root as *const Node, 0);
    for c in root.children.iter() {
        depths.insert(c as *const Node, 1);
    }

    for _ in 0..display_data.number_of_lines {
        match heap.pop() {
            Some(line) => {
                allowed_nodes.insert(line as *const Node);
                let d = *depths.get(&(line as *const Node)).unwrap_or(&1);
                if !keep_collapsed.contains(&line.name) {
                    for c in line.children.iter() {
                        depths.insert(c as *const Node, d + 1);
                    }
                    heap = add_children(display_data, line, heap, d + 1, false);
                }
            }
            None => break,
        }
    }
    let _ = Allowed { node: root, depth: 0 };
    Some(recursive_rebuilder(&allowed_nodes, root))
}

fn recursive_rebuilder(allowed_nodes: &HashSet<*const Node>, current: &Node) -> DisplayNode {
    let mut new_children: Vec<DisplayNode> = current
        .children
        .iter()
        .filter(|c| allowed_nodes.contains(&(*c as *const Node)))
        .map(|c| recursive_rebuilder(allowed_nodes, c))
        .collect();
    new_children.sort_by(|a, b| b.cmp(a));
    DisplayNode {
        name: current.name.clone(),
        size: current.size,
        children: new_children,
    }
}

/// Group all files by their extension.
pub fn get_all_file_types(top_level_nodes: &[Node], n: usize) -> Option<DisplayNode> {
    let mut map: std::collections::HashMap<String, u64> = std::collections::HashMap::new();
    for node in top_level_nodes {
        collect_file_types(node, &mut map);
    }
    let mut nodes: Vec<DisplayNode> = map
        .into_iter()
        .map(|(ext, size)| DisplayNode {
            name: PathBuf::from(ext),
            size,
            children: vec![],
        })
        .collect();
    nodes.sort_by(|a, b| b.cmp(a));
    nodes.truncate(n);
    let total = nodes.iter().fold(0u64, |acc, n| acc.wrapping_add(n.size));
    Some(DisplayNode {
        name: PathBuf::from("(total)"),
        size: total,
        children: nodes,
    })
}

fn collect_file_types(node: &Node, map: &mut std::collections::HashMap<String, u64>) {
    if node.children.is_empty() {
        if node.name.is_file() {
            let ext = match node.name.extension() {
                Some(e) => format!(".{}", e.to_string_lossy()),
                None => "(no extension)".to_string(),
            };
            let e = map.entry(ext).or_insert(0);
            *e = e.wrapping_add(node.size);
        }
    } else {
        for c in &node.children {
            collect_file_types(c, map);
        }
    }
}

#[allow(dead_code)]
pub fn is_a_parent_of(parent: &Path, child: &Path) -> bool {
    child.starts_with(parent) && child != parent
}
