    child_depth: usize,
    ignore_depth: bool,
) -> BinaryHeap<&'a Node> {
    if ignore_depth || child_depth <= display_data.depth {
        for c in file_or_folder.children.iter() {
            if passes_filters(c, display_data) {
                heap.push(c);
            }
        }
    }
    heap
}

struct Allowed<'a> {
    node: &'a Node,
    depth: usize,
}

fn fill_remaining_lines<'a>(
    mut heap: BinaryHeap<&'a Node>,
    root: &'a Node,
    display_data: &AggregateData,
    keep_collapsed: &HashSet<PathBuf>,
) -> Option<DisplayNode> {
    let mut allowed_nodes: HashSet<*const Node> = HashSet::new();
    allowed_nodes.insert(root as *const Node);

    // depth of each node is derived from the tree position; we track it via a map
    let mut depths: std::collections::HashMap<*const Node, usize> = std::collections::HashMap::new();
    depths.insert(root as *const Node, 0);
    for c in root.children.iter() {
        depths.insert(c as *const Node, 1);
    }

    for _ in 0..display_data.number_of_lines {
        match heap.pop() {
            Some(line) => {
                allowed_nodes.insert(line as *const Node);
                let d = *depths.get(&(line as *const Node)).unwrap_or(&1);
                if !keep_collapsed.contains(&line.name) {
                    for c in line.children.iter() {
                        depths.insert(c as *const Node, d + 1);
                    }
                    heap = add_children(display_data, line, heap, d + 1, false);
                }
            }
            None => break,
        }
    }
    let _ = Allowed { node: root, depth: 0 };
    Some(recursive_rebuilder(&allowed_nodes, root))
}

fn recursive_rebuilder(allowed_nodes: &HashSet<*const Node>, current: &Node) -> DisplayNode {
    let mut new_children: Vec<DisplayNode> = current
        .children
        .iter()
        .filter(|c| allowed_nodes.contains(&(*c as *const Node)))
        .map(|c| recursive_rebuilder(allowed_nodes, c))
        .collect();
    new_children.sort_by(|a, b| b.cmp(a));
    DisplayNode {
        name: current.name.clone(),
        size: current.size,
        children: new_children,
    }
}

/// Group all files by their extension.
pub fn get_all_file_types(top_level_nodes: &[Node], n: usize) -> Option<DisplayNode> {
    let mut map: std::collections::HashMap<String, u64> = std::collections::HashMap::new();
    for node in top_level_nodes {
        collect_file_types(node, &mut map);
    }
    let mut nodes: Vec<DisplayNode> = map
        .into_iter()
        .map(|(ext, size)| DisplayNode {
            name: PathBuf::from(ext),
            size,
            children: vec![],
        })
        .collect();
    nodes.sort_by(|a, b| b.cmp(a));
    nodes.truncate(n);
    let total = nodes.iter().fold(0u64, |acc, n| acc.wrapping_add(n.size));
    Some(DisplayNode {
        name: PathBuf::from("(total)"),
        size: total,
        children: nodes,
    })
}

fn collect_file_types(node: &Node, map: &mut std::collections::HashMap<String, u64>) {
    if node.children.is_empty() {
        if node.name.is_file() {
            let ext = match node.name.extension() {
                Some(e) => format!(".{}", e.to_string_lossy()),
                None => "(no extension)".to_string(),
            };
            let e = map.entry(ext).or_insert(0);
            *e = e.wrapping_add(node.size);
        }
    } else {
        for c in &node.children {
            collect_file_types(c, map);
        }
    }
}

