//! Minimal LS_COLORS support: parse the environment variable and produce
//! ANSI escape sequences for paths.
use std::collections::HashMap;
use std::fs;
use std::os::unix::fs::{FileTypeExt, MetadataExt, PermissionsExt};
use std::path::Path;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Color {
    Basic(u8),  // 0..=7
    Bright(u8), // 0..=7
    Fixed(u8),
    Rgb(u8, u8, u8),
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Style {
    pub foreground: Option<Color>,
    pub background: Option<Color>,
    pub bold: bool,
    pub dimmed: bool,
    pub italic: bool,
    pub underline: bool,
    pub blink: bool,
    pub reverse: bool,
    pub hidden: bool,
    pub strikethrough: bool,
}

impl Style {
    fn is_plain(&self) -> bool {
        *self == Style::default()
    }

    fn write_color(out: &mut String, c: &Color, fg: bool) {
        match c {
            Color::Basic(n) => out.push_str(&format!("{}{}", if fg { 3 } else { 4 }, n)),
            Color::Bright(n) => {
                out.push_str(&format!("{};5;{}", if fg { 38 } else { 48 }, 8 + n))
            }
            Color::Fixed(n) => out.push_str(&format!("{};5;{}", if fg { 38 } else { 48 }, n)),
            Color::Rgb(r, g, b) => {
                out.push_str(&format!("{};2;{};{};{}", if fg { 38 } else { 48 }, r, g, b))
            }
        }
    }

    pub fn paint(&self, text: &str) -> String {
        if self.is_plain() {
            return text.to_string();
        }
        let mut codes: Vec<String> = Vec::new();
        if self.bold {
            codes.push("1".into());
        }
        if self.dimmed {
            codes.push("2".into());
        }
        if self.italic {
            codes.push("3".into());
        }
        if self.underline {
            codes.push("4".into());
        }
        if self.blink {
            codes.push("5".into());
        }
        if self.reverse {
            codes.push("7".into());
        }
        if self.hidden {
            codes.push("8".into());
        }
        if self.strikethrough {
            codes.push("9".into());
        }
        if let Some(bg) = &self.background {
            let mut s = String::new();
            Style::write_color(&mut s, bg, false);
            codes.push(s);
        }
        if let Some(fg) = &self.foreground {
            let mut s = String::new();
            Style::write_color(&mut s, fg, true);
            codes.push(s);
        }
        format!("\x1b[{}m{}\x1b[0m", codes.join(";"), text)
    }

    /// Parse an ANSI sequence such as "01;34". Returns None for invalid input.
    pub fn from_ansi_sequence(code: &str) -> Option<Style> {
        let parts: Vec<u8> = code
            .split(';')
            .map(|p| p.parse::<u8>())
            .collect::<Result<Vec<u8>, _>>()
            .ok()?;
        let mut style = Style::default();
        let mut i = 0;
        while i < parts.len() {
            let p = parts[i];
            match p {
                0 => style = Style::default(),
                1 => style.bold = true,
                2 => style.dimmed = true,
                3 => style.italic = true,
                4 => style.underline = true,
                5 => style.blink = true,
                7 => style.reverse = true,
                8 => style.hidden = true,
                9 => style.strikethrough = true,
                30..=37 => style.foreground = Some(Color::Basic(p - 30)),
                39 => style.foreground = None,
                40..=47 => style.background = Some(Color::Basic(p - 40)),
                49 => style.background = None,
                90..=97 => style.foreground = Some(Color::Bright(p - 90)),
                100..=107 => style.background = Some(Color::Bright(p - 100)),
                38 | 48 => {
                    let mode = *parts.get(i + 1)?;
                    let color = match mode {
                        5 => {
                            let n = *parts.get(i + 2)?;
                            i += 2;
                            Color::Fixed(n)
                        }
                        2 => {
                            let r = *parts.get(i + 2)?;
                            let g = *parts.get(i + 3)?;
                            let b = *parts.get(i + 4)?;
                            i += 4;
                            Color::Rgb(r, g, b)
                        }
                        _ => return None,
                    };
                    if p == 38 {
                        style.foreground = Some(color);
                    } else {
                        style.background = Some(color);
                    }
                }
                _ => {}
            }
            i += 1;
        }
        Some(style)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Indicator {
    Normal,
    RegularFile,
    Directory,
    SymbolicLink,
    FIFO,
    Socket,
    Door,
    BlockDevice,
    CharacterDevice,
    OrphanedSymbolicLink,
    MissingFile,
    Setuid,
    Setgid,
    Sticky,
    OtherWritable,
    StickyAndOtherWritable,
    ExecutableFile,
    MultipleHardLinks,
