        }
        return;
    }

    if skip_total {
        let children: Vec<&DisplayNode> = root_node
            .get_children_from_node(display_data.initial.is_reversed)
            .collect();
        let n = children.len();
        for (count, c) in children.iter().enumerate() {
            let is_biggest = count == 0;
            let was_i_last = count == n - 1;
            display_node(c, &draw_data, is_biggest, was_i_last, max_bar_length, 1);
        }
    } else {
        display_node(root_node, &draw_data, true, true, max_bar_length, 0);
    }
}

fn screen_reader_lines(
    node: &DisplayNode,
    depth: usize,
    dd: &DisplayData,
    longest_name: usize,
    skip_total: bool,
    lines: &mut Vec<String>,
) {
    let idd = &dd.initial;
    let line = |n: &DisplayNode, d: usize| -> String {
        let name = get_printable_name(&n.name, !idd.short_paths);
        let pad = longest_name.saturating_sub(UnicodeWidthStr::width(name.as_str()));
        let size = size_string(n.size, idd);
        let pct = format!("{:.0}", dd.percent_size(n) * 100.0);
        format!(
            "{}{} {} {:>w$} {:>3}%",
            name,
            " ".repeat(pad),
            d,
            size,
            pct,
            w = dd.num_chars_needed_on_left_most
        )
    };
    fn rec(
        node: &DisplayNode,
        depth: usize,
        dd: &DisplayData,
        line: &dyn Fn(&DisplayNode, usize) -> String,
        lines: &mut Vec<String>,
    ) {
        if dd.initial.is_reversed {
            lines.push(line(node, depth));
            for c in node.get_children_from_node(true) {
                rec(c, depth + 1, dd, line, lines);
            }
        } else {
            for c in node.get_children_from_node(false) {
                rec(c, depth + 1, dd, line, lines);
            }
            lines.push(line(node, depth));
        }
    }
    if skip_total {
        for c in node.get_children_from_node(idd.is_reversed) {
            rec(c, depth, dd, &line, lines);
        }
    } else {
        rec(node, depth, dd, &line, lines);
    }
}

fn display_node(
    node: &DisplayNode,
    draw_data: &DrawData,
    is_biggest: bool,
    is_last: bool,
    max_bar_length: usize,
    depth: usize,
) {
    let dd = draw_data.display_data;
    let num_bars = ((dd.percent_size(node) * max_bar_length as f32) as usize + 1).min(max_bar_length);
    let mut fills = draw_data.percent_bar.clone();
    fills.push(num_bars);

    let has_children = !node.children.is_empty();
    // In non-reversed mode the node that is displayed first ('is_last' in
    // iteration order) gets the corner character.
    let corner = if dd.initial.is_reversed { is_last } else { is_last };
    let tree_chars = dd.get_tree_chars(corner, has_children);
    let indent_str = format!("{}{}", draw_data.indent, tree_chars);

    let child_indent = format!(
        "{}{}",
        draw_data.indent,
        if corner { "  " } else { "│ " }
    );
    let child_draw_data = DrawData {
        indent: child_indent,
        percent_bar: fills.clone(),
        display_data: dd,
    };

    let children: Vec<&DisplayNode> = node
        .get_children_from_node(dd.initial.is_reversed)
        .collect();
    let n = children.len();

    if dd.initial.is_reversed {
        print_line(node, &indent_str, &fills, is_biggest, max_bar_length, depth, dd);
        for (count, c) in children.iter().enumerate() {
            let c_is_biggest = count == 0;
            let c_is_last = count == n - 1;
            display_node(c, &child_draw_data, c_is_biggest, c_is_last, max_bar_length, depth + 1);
        }
    } else {
        for (count, c) in children.iter().enumerate() {
            let c_is_biggest = count == n - 1;
            let c_is_last = count == 0;
            display_node(c, &child_draw_data, c_is_biggest, c_is_last, max_bar_length, depth + 1);
        }
        print_line(node, &indent_str, &fills, is_biggest, max_bar_length, depth, dd);
    }
}

fn generate_bar(fills: &[usize], max_bar_length: usize, bars_on_right: bool) -> String {
    // fills[0] is the root (always full), fills[i] is the node at depth i,
    // the last element is the node itself.
    let mut bar = String::with_capacity(max_bar_length * 3);
    let own = *fills.last().unwrap_or(&0);
    for i in 0..max_bar_length {
        let c = if i < own {
            BLOCKS[0]
        } else {
            // find the nearest ancestor (deepest) covering this position
            let mut ch = BLOCKS[4];
            let depth_count = fills.len() - 1; // index of own
            let mut d = depth_count;
            while d > 0 {
                d -= 1;
                if i < fills[d] {
                    ch = match d {
                        0 => BLOCKS[4],
                        1 => BLOCKS[3],
                        2 => BLOCKS[2],
                        _ => BLOCKS[1],
                    };
                    break;
                }
            }
            ch
        };
        bar.push(c);
    }
    if bars_on_right {
        bar.chars().rev().collect()
    } else {
        bar
    }
}

// padding so that the panic below is reported at the expected location
