//
//
//
fn print_line(
    node: &DisplayNode,
    indent_str: &str,
    fills: &[usize],
    is_biggest: bool,
    max_bar_length: usize,
    _depth: usize,
    dd: &DisplayData,
) {
    let idd = &dd.initial;
    let name = get_printable_name(&node.name, !idd.short_paths);
    let sep = if idd.by_filetime { "" } else { " " };
    let indent_width = UnicodeWidthStr::width(indent_str);
    let name_width = UnicodeWidthStr::width(name.as_str());

    let pretty_name = if max_bar_length > 0 {
        // pad the name so the bars line up
        let used = indent_width + 1 + name_width;
        let padding = dd.longest_string_length.saturating_sub(used);
        format!("{}{}", name, " ".repeat(padding))
    } else {
        let prefix_width = indent_width + UnicodeWidthStr::width(sep);
        let allowed_for_name = dd.allowed_width as isize - prefix_width as isize;
        if allowed_for_name < 2 {
    panic!("Terminal width not wide enough to draw directory tree");
        }
        let allowed_for_name = allowed_for_name as usize;
        if name_width > allowed_for_name {
            let truncated: String = name.chars().take(allowed_for_name - 2).collect();
            format!("{}..", truncated)
        } else {
            name
        }
    };

    let size_str = size_string(node.size, idd);
    let pretty_size = format!("{:>w$}", size_str, w = dd.num_chars_needed_on_left_most);
    let pretty_size = if idd.colors_on && is_biggest {
        format!("\x1b[31m{}\x1b[0m", pretty_size)
    } else {
        pretty_size
    };

    let pretty_name = if idd.colors_on {
        match dd.ls_colors.style_for_path(&node.name) {
            Some(style) => style.paint(&pretty_name),
            None => pretty_name,
        }
    } else {
        pretty_name
    };

    let bar_part = if max_bar_length > 0 && !idd.by_filetime {
        let bar = generate_bar(fills, max_bar_length, idd.bars_on_right);
        let pct = format!("{:.0}", dd.percent_size(node) * 100.0);
        format!("│{} │ {:>3}%", bar, pct)
    } else {
        String::new()
    };

    println!("{} {}{}{}{}", pretty_size, indent_str, sep, pretty_name, bar_part);
}
