use std::cmp::max;
use std::path::Path;

use unicode_width::UnicodeWidthStr;

use crate::display_node::DisplayNode;
use crate::lscolors::LsColors;

pub static UNITS: [char; 5] = ['P', 'T', 'G', 'M', 'K'];
static BLOCKS: [char; 5] = ['█', '▓', '▒', '░', ' '];

pub struct InitialDisplayData {
    pub short_paths: bool,
    pub is_reversed: bool,
    pub colors_on: bool,
    pub by_filecount: bool,
    pub by_filetime: bool,
    pub is_screen_reader: bool,
    pub output_format: String,
    pub bars_on_right: bool,
}

pub struct DisplayData {
    pub initial: InitialDisplayData,
    pub num_chars_needed_on_left_most: usize,
    pub base_size: u64,
    pub longest_string_length: usize,
    pub allowed_width: usize,
    pub ls_colors: LsColors,
}

impl DisplayData {
    fn percent_size(&self, node: &DisplayNode) -> f32 {
        if self.base_size == 0 {
            return 0.0;
        }
        node.size as f32 / self.base_size as f32
    }

    fn get_tree_chars(&self, was_i_last: bool, has_children: bool) -> &'static str {
        if self.initial.is_reversed {
            match (was_i_last, has_children) {
                (true, true) => "└─┬",
                (true, false) => "└──",
                (false, true) => "├─┬",
                (false, false) => "├──",
            }
        } else {
            match (was_i_last, has_children) {
                (true, true) => "┌─┴",
                (true, false) => "┌──",
                (false, true) => "├─┴",
                (false, false) => "├──",
            }
        }
    }
}

pub struct DrawData<'a> {
    pub indent: String,
    pub percent_bar: Vec<usize>,
    pub display_data: &'a DisplayData,
}

/// Escapes control characters in the same way the original tool does.
pub fn get_printable_name<P: AsRef<Path>>(dir_name: P, long_paths: bool) -> String {
    let dir_name = dir_name.as_ref();
    let printable_name = if long_paths {
        dir_name.to_string_lossy().into_owned()
    } else {
        match dir_name.file_name() {
            Some(n) => n.to_string_lossy().into_owned(),
            None => dir_name.to_string_lossy().into_owned(),
        }
    };
    escape_name(&printable_name)
}

fn escape_name(name: &str) -> String {
    let mut out = String::with_capacity(name.len());
    for c in name.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '\t' => out.push_str("\\t"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            c if (c as u32) < 0x20 || c as u32 == 0x7f => {
                out.push_str(&format!("\\x{:02X}", c as u32))
            }
            c => out.push(c),
        }
    }
    out
}

pub fn human_readable_number(size: u64, output_format: &str) -> String {
    match output_format {
        "b" => format!("{}B", size),
        "k" => format!("{}K", size / 1024),
        "m" => format!("{}M", size / 1024u64.pow(2)),
        "g" => format!("{}G", size / 1024u64.pow(3)),
        "t" => format!("{}T", size / 1024u64.pow(4)),
        "kb" => format!("{}K", size / 1000),
        "mb" => format!("{}M", size / 1000u64.pow(2)),
        "gb" => format!("{}G", size / 1000u64.pow(3)),
        "tb" => format!("{}T", size / 1000u64.pow(4)),
        "si" => human_units(size, 1000),
        _ => human_units(size, 1024),
    }
}

fn human_units(size: u64, base: u64) -> String {
    for (i, u) in UNITS.iter().enumerate() {
        let marker = base.pow((UNITS.len() - i) as u32);
        if size >= marker {
            let v = size as f64 / marker as f64;
            if v < 10.0 {
                return format!("{:.1}{}", v, u);
            } else {
                return format!("{}{}", v as u64, u);
            }
        }
    }
    format!("{}B", size)
}

pub fn thousands_separated(size: u64) -> String {
    let s = size.to_string();
    let bytes = s.as_bytes();
    let mut out = String::new();
    for (i, b) in bytes.iter().enumerate() {
        if i > 0 && (bytes.len() - i) % 3 == 0 {
            out.push(',');
        }
        out.push(*b as char);
    }
    out
}

pub fn format_size_for_json(size: u64, output_format: &str, by_filecount: bool) -> String {
    if by_filecount {
        thousands_separated(size)
    } else {
        human_readable_number(size, output_format)
    }
}

fn filetime_string(secs: u64) -> String {
    let dt = chrono::DateTime::from_timestamp(secs as i64, 0);
    match dt {
        Some(dt) => dt.format("%Y-%m-%dT%H:%M:%S").to_string(),
        None => format!("{}", secs),
    }
}

fn size_string(size: u64, idd: &InitialDisplayData) -> String {
    if idd.by_filecount {
