use std::collections::HashSet;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};

/// Normalise a path by collecting its components (removes trailing slashes
/// and redundant separators / inner "." components).
pub fn normalize_path<P: AsRef<Path>>(path: P) -> PathBuf {
    path.as_ref().components().collect()
}

pub fn is_a_parent_of<P: AsRef<Path>>(parent: P, child: P) -> bool {
    let parent = parent.as_ref();
    let child = child.as_ref();
    child.starts_with(parent) && child != parent
}

/// Remove duplicated directories and directories that are contained in other
/// supplied directories.
pub fn simplify_dir_names(filenames: &[String]) -> Vec<PathBuf> {
    let mut top_level_names: Vec<PathBuf> = Vec::new();
    for t in filenames {
        let top_level_name = normalize_path(t);
        let mut can_add = true;
        let mut to_remove: Vec<usize> = Vec::new();
        for (i, tt) in top_level_names.iter().enumerate() {
            if is_a_parent_of(&top_level_name, tt) {
                to_remove.push(i);
            } else if is_a_parent_of(tt, &top_level_name) || tt == &top_level_name {
                can_add = false;
            }
        }
        for i in to_remove.into_iter().rev() {
            top_level_names.remove(i);
        }
        if can_add {
            top_level_names.push(top_level_name);
        }
    }
    top_level_names
}

pub fn get_filesystem_devices(paths: &[PathBuf], follow_links: bool) -> HashSet<u64> {
    paths
        .iter()
        .filter_map(|p| {
            let md = if follow_links {
                std::fs::metadata(p)
            } else {
                std::fs::symlink_metadata(p)
            };
            md.ok().map(|m| m.dev())
        })
        .collect()
}

fn size_of_fd(fd: libc::c_int) -> Option<(usize, usize)> {
    let mut ws: libc::winsize = unsafe { std::mem::zeroed() };
    let r = unsafe { libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) };
    if r == 0 && ws.ws_col > 0 && ws.ws_row > 0 {
        Some((ws.ws_col as usize, ws.ws_row as usize))
    } else {
        None
    }
}

/// Size of the terminal connected to stdout, stderr or stdin (in that order).
pub fn terminal_size() -> Option<(usize, usize)> {
    size_of_fd(1)
        .or_else(|| size_of_fd(2))
        .or_else(|| size_of_fd(0))
}

pub fn is_terminal_present() -> bool {
    terminal_size().is_some()
}
