static DEFAULT_NUMBER_OF_LINES: usize = 20;
static DEFAULT_TERMINAL_WIDTH: usize = 80;

fn get_regex_value(vals: Option<clap::parser::ValuesRef<String>>) -> Vec<Regex> {
    vals.unwrap_or_default()
        .map(|reg| {
            Regex::new(reg).unwrap_or_else(|err| {
                eprintln!("Ignoring bad value for regex {:?}", err);
                std::process::exit(1)
            })
        })
        .collect()
}

fn get_number_of_lines(config: &Config, options: &ArgMatches, height: Option<usize>) -> usize {
    match config.get_number_of_lines(options) {
        Some(n) => n,
        None => {
            if config.depth_was_set(options) {
                usize::MAX
            } else {
                match height {
                    Some(h) => std::cmp::max(h.saturating_sub(10), DEFAULT_NUMBER_OF_LINES),
                    None => DEFAULT_NUMBER_OF_LINES,
                }
            }
        }
    }
}

fn read_files_from(file: &str, nul_separated: bool) -> Option<Vec<String>> {
    let mut content = String::new();
    let result = if file == "-" {
        std::io::stdin().read_to_string(&mut content).map(|_| ())
    } else {
        std::fs::read_to_string(file).map(|c| {
            content = c;
        })
    };
    if let Err(e) = result {
        eprintln!("Failed to read file: {}", e);
        return None;
    }
    let paths: Vec<String> = if nul_separated {
        content
            .split('\0')
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string())
            .collect()
    } else {
        content.lines().map(|s| s.to_string()).collect()
    };
    if paths.is_empty() {
        eprintln!("No files provided, defaulting to current directory");
        return None;
    }
    Some(paths)
}

fn available_memory_bytes() -> Option<u64> {
    let content = std::fs::read_to_string("/proc/meminfo").ok()?;
    for line in content.lines() {
        if let Some(rest) = line.strip_prefix("MemAvailable:") {
            let kb: u64 = rest.trim().trim_end_matches("kB").trim().parse().ok()?;
            return Some(kb * 1024);
        }
    }
    None
}

fn default_stack_size() -> usize {
    let large_stack: usize = 1024 * 1024 * 1024;
    match available_memory_bytes() {
        Some(avail) if avail > large_stack as u64 => large_stack,
        _ => 1024 * 1024,
    }
}

fn main() {
    let options = cli::build_cli().get_matches();
    let config = get_config(options.get_one::<String>("config"));

    let errors: Arc<Mutex<RuntimeErrors>> = Arc::new(Mutex::new(RuntimeErrors::default()));
    let errors_for_rayon = errors.clone();

    // ------------------------------------------------------------------
    // Target directories
    // ------------------------------------------------------------------
    let files_from = config.get_files_from(&options);
    let files0_from = config.get_files0_from(&options);
    let target_dirs: Vec<String> = if let Some(f) = files_from.as_deref() {
        read_files_from(f, false).unwrap_or_else(|| vec![".".to_string()])
    } else if let Some(f) = files0_from.as_deref() {
        read_files_from(f, true).unwrap_or_else(|| vec![".".to_string()])
    } else {
        match options.get_many::<String>("params") {
            Some(values) => values.cloned().collect(),
            None => vec![".".to_string()],
        }
    };

    let summarize_file_types = options.get_flag("file_types");

    let filter_regexs = get_regex_value(options.get_many::<String>("filter"));
    let mut invert_filter_regexs = get_regex_value(options.get_many::<String>("invert_filter"));

    // ------------------------------------------------------------------
    // Terminal
    // ------------------------------------------------------------------
    let term = terminal_size();
    let terminal_width = match options.get_one::<usize>("terminal_width") {
        Some(w) => *w,
        None => term.map(|(w, _)| w).unwrap_or(DEFAULT_TERMINAL_WIDTH),
    };
    let terminal_height = term.map(|(_, h)| h);

    let depth = config.get_depth(&options);
    let number_of_lines = get_number_of_lines(&config, &options, terminal_height);

    let no_colors = config.get_no_colors(&options);
    let force_colors = config.get_force_colors(&options);
    let is_colors = if force_colors {
        true
    } else if no_colors {
        false
    } else {
        is_terminal_present()
    };

    // ------------------------------------------------------------------
    // Ignore / filter options
    // ------------------------------------------------------------------
    let ignore_directories: Vec<PathBuf> = options
        .get_many::<String>("ignore_directory")
        .map(|v| v.map(PathBuf::from).collect())
        .unwrap_or_default();

    if let Some(file) = options.get_one::<String>("ignore_all_in_file") {
        // The file must exist, otherwise this is a hard error.
        let content = std::fs::read_to_string(file)
            .unwrap();
        for line in content.lines() {
            if let Ok(r) = Regex::new(line) {
                invert_filter_regexs.push(r);
            }
        }
    }

    let by_filecount = options.get_flag("by_filecount");
    let by_filetime = options
        .get_one::<String>("filetime")
        .map(|s| match s.to_lowercase().as_str() {
            "a" => FileTime::Accessed,
            "c" => FileTime::Changed,
            _ => FileTime::Modified,
        });
    let limit_filesystem = options.get_flag("limit_filesystem");
    let follow_links = options.get_flag("dereference_links");

    let simplified_dirs = simplify_dir_names(&target_dirs);
    let allowed_filesystems = if limit_filesystem {
        get_filesystem_devices(&simplified_dirs, follow_links)
    } else {
        HashSet::new()
    };

    let mut ignored_full_path: HashSet<PathBuf> = HashSet::new();
    for x in &ignore_directories {
        for d in &simplified_dirs {
            ignored_full_path.insert(d.join(x));
        }
        if x.is_absolute() {
            if let Ok(c) = std::fs::canonicalize(x) {
                ignored_full_path.insert(c);
            }
        }
    }

    let keep_collapsed: HashSet<PathBuf> = {
        let mut set = HashSet::new();
        if let Some(vals) = options.get_many::<String>("collapse") {
            for x in vals {
                for d in &simplified_dirs {
                    set.insert(d.join(x));
                }
            }
        }
        set
    };

    let output_format = config.get_output_format(&options);
    let no_progress = config.get_disable_progress(&options);

    let current = get_current_date_epoch_seconds();
    let filter_modified_time =
        get_filter_time_operator(options.get_one::<String>("mtime"), current);
    let filter_accessed_time =
        get_filter_time_operator(options.get_one::<String>("atime"), current);
    let filter_changed_time =
        get_filter_time_operator(options.get_one::<String>("ctime"), current);

    let mut indicator = PIndicator::build_me();
    if !no_progress {
        indicator.spawn(output_format.clone());
    }

    let use_apparent_size = config.get_apparent_size(&options);
    let ignore_hidden = config.get_ignore_hidden(&options);

    let threads_to_use = config.get_threads(&options);
    let stack_size = config
        .get_custom_stack_size(&options)
        .unwrap_or_else(default_stack_size);

    let min_size = config.get_min_size(&options);
    let only_dir = config.get_only_dir(&options);
    let only_file = config.get_only_file(&options);
    let using_a_filter = !filter_regexs.is_empty() || !invert_filter_regexs.is_empty();
    let short_paths = !config.get_full_paths(&options);
    let is_reversed = config.get_reverse(&options);
    let is_screen_reader = config.get_screen_reader(&options);
    let bars_on_right = config.get_bars_on_right(&options);
    let no_bars = config.get_no_bars(&options);
    let skip_total = config.get_skip_total(&options);
    let output_json = config.get_output_json(&options);
    let print_errors = config.get_print_errors(&options);

    let progress_data = indicator.data.clone();

    let worker = std::thread::Builder::new()
        .stack_size(stack_size)
        .spawn(move || {
            let mut pool_builder = rayon::ThreadPoolBuilder::new().stack_size(stack_size);
            if let Some(t) = threads_to_use {
                pool_builder = pool_builder.num_threads(t);
            }
            if pool_builder.build_global().is_err() {
                eprintln!("Problem initializing rayon, try: export RAYON_NUM_THREADS=1");
            }

            let walk_data = WalkData {
                ignore_directories: ignored_full_path,
                filter_regex: &filter_regexs,
                invert_filter_regex: &invert_filter_regexs,
                allowed_filesystems,
                filter_modified_time,
                filter_accessed_time,
                filter_changed_time,
                use_apparent_size,
                by_filecount,
                by_filetime,
                ignore_hidden,
                follow_links,
                progress_data,
                errors: errors_for_rayon,
            };

            let top_level_nodes = walk_it(simplified_dirs, &walk_data);

            let tree = if summarize_file_types {
                get_all_file_types(&top_level_nodes, number_of_lines)
            } else {
                let agg_data = AggregateData {
                    min_size,
                    only_dir,
                    only_file,
                    number_of_lines,
                    depth,
                    using_a_filter,
                };
                get_biggest(top_level_nodes, &agg_data, &keep_collapsed)
            };

            // Must have stopped the indicator before printing to stderr
            indicator.stop();

            let final_errors = walk_data.errors.lock().unwrap();
            let had_not_found = !final_errors.file_not_found.is_empty();
            if had_not_found {
                let err = final_errors
                    .file_not_found
                    .iter()
                    .map(|a| a.as_str())
                    .collect::<Vec<&str>>()
                    .join(", ");
                eprintln!("No such file or directory: {}", err);
            }
            if !final_errors.no_permissions.is_empty() {
                if print_errors {
                    let err = final_errors
                        .no_permissions
                        .iter()
                        .map(|a| a.as_str())
                        .collect::<Vec<&str>>()
                        .join(", ");
                    eprintln!("Did not have permissions for directories: {}", err);
                } else {
                    eprintln!(
                        "Did not have permissions for all directories (add --print-errors to see errors)"
                    );
                }
            }
            if !final_errors.unknown_error.is_empty() {
                let err = final_errors
                    .unknown_error
                    .iter()
                    .map(|a| a.as_str())
                    .collect::<Vec<&str>>()
                    .join(", ");
                eprintln!("Unknown Error: {}", err);
            }
            drop(final_errors);

            let root_node = match tree {
                Some(t) => t,
                None => std::process::exit(1),
            };
            if root_node.children.is_empty() && had_not_found {
                std::process::exit(1);
            }

            if output_json {
                let json_node = to_json_node(&root_node, &output_format, by_filecount);
                let out = serde_json::to_string(&json_node)
                    .unwrap();
                println!("{}", out);
            } else {
                let idd = InitialDisplayData {
                    short_paths,
                    is_reversed,
                    colors_on: is_colors,
                    by_filecount,
                    by_filetime: by_filetime.is_some(),
                    is_screen_reader,
                    output_format,
                    bars_on_right,
                };
                draw_it(idd, no_bars, terminal_width, &root_node, skip_total);
            }
        })
        .expect("failed to spawn worker thread");

    if worker.join().is_err() {
        std::process::exit(101);
    }
}
